def authorize_action(approval, payload_hash, approver, now):
    if approval['payload_hash'] != payload_hash: raise PermissionError('payload changed')
    if approver not in approval['allowed_approvers']: raise PermissionError('approver denied')
    if now >= approval['expires_at'] or approval['used']: raise PermissionError('approval expired or replayed')
    approval['used'] = True
    return True
